 BPOINT        jr NZ,DETBONOLY       INC L        CALL BPOINT        jr NZ,DETBONOLY        INC C        CALL BPOINTDETBONOLY       POP HL,BC        RET       IF 0RND        PUSH HL        LD HL,(SEED)        LD A,H        AND 31        LD H,A        LD A,(HL)        INC H        INC HL        RLCA         ADD A,(HL)        LD (SEED),HL        POP HL        RET       ENDIF DELPERS       IF byting        LD (IX),IDerased       ELSE        PUSH BC,DE        PUSH IX        POP DE        LD HL,Lunit        ADD HL,DEdelper0 LD A,(HL),(DE),A        OR A        JR Z,delpQ        LD BC,Lunit        LDIR         JR delper0delpQ  POP DE,BC       ENDIF         RET PHASER;H=last phase #;L=time;если на выходе sign=M, то анимация перезапущена сначала        DEC (IX+10)        RET P        LD (IX+10),L        DEC (IX+1)        RET P        LD (IX+1),H        RET COLLBq       POP IX        OR A        RET COLLBy        PUSH IX        POP HL       POP IX        SCF         RET COLLBALL;коллизии с бонусами;CY=коллизия;L=herowdt (ширина одного бока в полупикселях);H=herohgt*2 (в полупикселях)        LD A,L,(COLLwdt),A        LD A,H,(COLLhgt2),A       PUSH IX        LD IX,HEROESCOLLB0        LD A,(IX)        OR A        jr Z,COLLBq        LD HL,16<8+8        CP IDapple        jr C,COLLBn        CP IDlog        jr NC,COLLBn       ;CP IDkey       ;JZ COLLBid       ;CP IDexit       ;JZ COLLBid       ;CP IDdiam       ;JZ COLLBid       ;CP IDdiam       ;JZ COLLBid       ;CP IDweight       ;JZ COLLBid       ;CP IDhourglass       ;JNZ COLLBnCOLLBid;все размеры - в двойных пикселях!        LD A,LCOLLwdt=$+1        ADD A,0 ;herowdt        LD LY,A        LD A,H        LD HY,A;коллизия,если (abs(X-Xb)<LY)and( (Y-Yb<herohgt*2)or(Yb-Y<HY) );abs(X-Xb)<LY?        LD L,(IX+4) ;        LD H,(IX+5) ;Xb        XOR A        SBC HL,DE ;Xb-X        jr NC,COLLBx1        SUB L        LD L,A        SBC A,A        SUB H        LD H,ACOLLBx1        INC H        DEC H        jr NZ,COLLBn        LD A,L        CP LY ;monsterwdt+herowdt        jr NC,COLLBn;Yb-Y<HY?        LD L,(IX+2) ;        LD H,(IX+3) ;Yb        XOR A        SBC HL,BC ;Yb-Y        INC H        DEC H        jr NZ,COLLBYn        LD A,L        CP HY ;monsterhgt*2        jr C,COLLByCOLLBYn;Y-Yb<herohgt*2?        XOR A        SUB L        LD L,A        SBC A,A        SUB H        LD H,A    ;HL=Y-Yb        INC H        DEC H        jr NZ,COLLBn        LD A,LCOLLhgt2=$+1        CP 0 ;herohgt*2        jr C,COLLByCOLLBn        PUSH BC        LD BC,Lunit        ADD IX,BC        POP BC        JR COLLB0BONCOLL;проверка коллизии с героем;IN: A=-HGTbonus;OUT:CY=коллизия        LD HL,(HEROES+2) ;Yhero        OR A        SBC HL,BC ;Yhero-Y = -HGTbonus...+HGThero       INC H       jr NZ,BONCOLLnU        CP L        RET NC       DEC H        JR BONCOLLyUBONCOLLnU        OR A       DEC H        RET NZ        LD A,L        CP 48 ;herohgt*2        RET NCBONCOLLyU        LD HL,(HEROES+4) ;Xhero        OR A        SBC HL,DE ;Xhero-X        JP P,BONCOLnNEG        XOR A        SUB L        LD L,A        SBC A,A        SUB H        LD H,ABONCOLnNEG        LD A,H        OR A        RET NZ        LD A,L        CP 24+24 ;herowdt+bonuswdt        RET ;управление героемCPlrfbottletime=$+1        LD HL,0        DEC HL       LD A,H       OR L       LD A,fxbottleend       CALL Z,AFXPRAY        BIT 7,H       LD A,(IX+6) ;dY        jr NZ,_CPnbt ;NZ=не bottle        LD (bottletime),HL        LD A,(MKEY)        LD L,A        AND #30        CP #30        LD A,L        jr Z,$+4        XOR #30        LD (MKEY),A_CPnbtbouncedX=$+1       LD A,-1       RLA        jr NC,hstrlwall ;можно отскакивать об стену       LD A,(bouncedY)      ;RLA      ;jr C,hstyr ;в воздухе не разгоняем и не тормозим                ;4 фрейма после контакта м