 GETdY        LD L,(IX+6) ;speedY        LD A,L        RLA         SBC A,A        LD H,A        RET YplusdY        PUSH HL        ADD HL,BC        LD B,H        ld C,L        POP HL        RET XplusdX        PUSH HL        ADD HL,DE        EXD         POP HL        RET        IF 0CPpol;NC=пересекли пол        LD A,B        SUB polY/256        RET C        RET NZ        LD A,C        CP polY        RET CPpotol;C=пересекли потолок        LD A,B        OR A        RET NZ       ;CALL GETbubHGT       LD A,24*2        SUB C        NEG ;A=Y-hgt        CP potolY        RET GETbubHGT;считаем высоту персонажа       PUSH HL        LD L,0        LD A,(IX)        CP IDbub32        JNZ $+4        LD L,32*2        CP IDbub16        JNZ $+4        LD L,16*2        CP IDbub8        JNZ $+4        LD L,8*2        CP IDharp        JNZ $+4        LD L,18*2        LD A,L       POP HL        RET        ENDIF BOUNCE       LD A,-1       LD (bouncedX),A       LD A,(bouncedY)       SCF        RRA        LD (bouncedY),A ;нельзя объединять,а то лезет по стене        CALL GETdY ;HL=dY     ;LD A,(timer)     ;AND 3     ;JNZ $+3       INC HL ;гравитация        CALL YplusdY        BIT 7,L        jr NZ,IQCPPOT       CALL DETPOL      jr C,IQNJY   ;ломаем пол (A=номер плитки)       ;INC L        DEC L        jr Z,IQnelom      PUSH BC,DE        CALL BOUNCEGETTYPE       CP IDdoska       jr NZ,IQpopnelom       LD (HL),IDdoskabrk        CALL dEBMAPP        XOR A        CALL dEBMALU       IF fx        LD A,fxcrack        CALL AFXPRAY       ENDIF IQpopnelom      POP DE,BCIQnelom      ;JZ IQyNIZ      ; CALL CPpol      ; JC IQNJY      ; LD BC,polY      ; JR IQypolIQyNIZ        LD A,C        AND #F0        LD C,AIQypol       XOR A       LD (bouncedY),A        LD A,LY        LD L,A        JR IQNJYIQCPPOT       CALL DETPOTOL      jr C,IQNPOT        PUSH DE,HL        CALL BOUNCEGETTYPE        POP HL,DE      ;JNC IQyWERH      ;  CALL CPpotol      ;  JNC IQNPOT;IQyWERH        LD C,(IX+2)        LD B,(IX+3)       ;LD A,C       ;OR #F       ;LD C,AIQypotol        XOR A       LD (bouncedY),A        SUB L        LD L,AIQNPOTIQNJY        LD (IX+6),L        LD (IX+2),C ;Y        LD (IX+3),B ;        CALL GETdX        CALL XplusdX    ;если по X нулевая скорость, то отбросить от препятствия       LD A,L       OR A       jr NZ,IQXn0       CALL DETPRVO        jr C,IQX0nPIQX0yP  DEC L        JR IQNJXIQX0nP       CALL DETLEVO        jr C,IQX0nLIQX0yL  INC LIQX0nL  JR IQNJXIQXn0        BIT 7,L        jr NZ,IQVLEVO      CALL DETLEVO ;препятствие там, ОТКУДА мы - разгон      jr NC,IQX0yL       CALL DETPRVO      ;JNC IQYJX      ; LD A,D      ; CP 2        JR C,IQNJX        JR IQYJXBRKIQVLEVO      CALL DETPRVO ;препятствие там, ОТКУДА мы - разгон      jr NC,IQX0yP       CALL DETLEVO      JR C,IQNJX      ;JNC IQYJX      ; BIT 7,D      ; JR Z,IQNJXIQYJXBRK   ;ломаем стекло (A=номер плитки)      PUSH BC     PUSH HL        CALL BOUNCEGETTYPE       CP IDglassV       jr NZ,IQpopnelomV        LD A,(IX+7) ;dX        OR A        JP P,$+5        NEG         CP 15        jr C,IQpopnelomV       LD (HL),IDglassVbr        CALL dEBMAPP        XOR A        CALL dEBMAVU       IF fx        LD A,fxglassbreak        CALL AFXPRAY       ENDIF IQpopnelomVIQnelomV     POP HL      POP    BCIQYJX   LD E,(IX+4)        LD D,(IX+5)        XOR A       LD (bouncedX),A        SUB L        LD L,AIQNJX   LD (IX+7),L        LD (IX+4),E ;X        LD (IX+5),D ;       LD A,(bouncedX)       RLA         LD A,(IX+7) ;dX       jr NC,SNDBOUNCE       LD A,(bouncedY)       RLA        RET C       LD A,(IX+6) ;dY       OR A       RET ZSNDBOUNCE   ;громкость=f(скорость)        OR A        JP P,$+5        NEG         CP 15 ;зашкал уберет только IMER        jr C,$+4        LD A,15        LD HL,tvolspd        ADD A,L        LD L,A        ADC A,H        SUB L        LD H,A        LD A,(HL)       PUSH DE       IF fx       PUSH BC        SUB 12        LD C,ABOUNCESOUNDTYPE=$+1        LD A,0        CP IDglassV        jr Z,BSOUGL        CP IDbeton        jr Z,$+4        CP IDbetonV        LD A,fxbeton        jr Z,BSOUOK        LD A,fxderewo        JR BSOUOKBSOUGL  LD A,fxglassBSOUOK  CALL AFXPRAYVOL       POP BC       ELSE         LD DE,BSG        CALL NEWSAMPVOL       ENDIF        POP DE        RET tvolspd        db 0x09,0x09,0x09,0x0A,0x0A,0x0A,0x0B,0x0B,0x0C,0x0C,0x0C,0x0D,0x0D,0x0E,0x0E,0x0EBOUNCEGETTYPE      LD L,A      LD H,0      LD E,L      ld D,H      ADD HL,HL      add HL,HL ;*4      ADD HL,DE       ;*5      ADD HL,HL      add HL,DE ;*11      LD DE,HEROES      ADD HL,DE       LD A,(HL)      LD (BOUNCESOUNDTYPE),A        RET LISTEND;ищем конец списка персонажей        PUSH BC        PUSH IX        POP HL        XOR A        LD BC,Lunit        ADD HL,BC        CP (HL)        jr NZ,$-2        POP BC        RET _ARR_L        LD A,(IX+10) ;time        ADD A,16        LD (IX+10),A        LD HL,2        JP P,$+6        LD HL,-2        ADD HL,DE        LD (IX+4),L        LD (IX+5),H ;X        JP programQ_ARU_D        LD A,(IX+10) ;time        ADD A,16        LD (IX+10),A        LD HL,2        JP P,$+6        LD HL,-2        ADD HL,BC        LD (IX+2),L        LD (IX+3),H ;Y        JP programQ_SPIDER        LD A,(IX+8) ;energy        ADD A,1        LD (IX+8),A        LD HL,2        JP P,$+6        LD HL,-2        ADD HL,BC        LD (IX+2),L        LD (IX+3),H ;Y        LD A,-24 ;-HGTпаука        CALL BONCOLL        JP NC,programQ       IF fxSJEDEN=$       OR A ;55=не съеден        LD A,fxekill        CALL C,AFXPRAY        LD A,55+128        LD (SJEDEN),A       ENDIF         LD A,1 ;lost        LD (gameover),A        JP programQ_HERO        LD A,(IX+6) ;dY        CPL         ADD A,4;2        JP M,$+4        XOR A        LD LY,A;-0        LD A,B        SUB dieY/256       jr C,_HEROnfdll       jr NZ,_HEROnfdll        LD A,C        CP dieY&0xff       jr C,_HEROnfdll        LD A,1 ;lost        LD (gameover),A_HEROnfdll        LD A,B        SUB fallY/256       jr C,_HEROnfall       jr NZ,_HEROnfall        LD A,C        CP fallY&0xff       jr C,_HEROnfall        PUSH DE        LD HL,(falladd)        LD DE,16        ADD HL,DE        LD (falladd),HL        EXD         ADD HL,BC        LD B,H        ld C,L        LD (IX+2),C        LD (IX+3),B ;Y       IF fxUPAL=$       OR A ;55=не падал        LD A,fxfall        CALL C,AFXPRAY        LD A,55+128        LD (UPAL),A       ENDIF         POP DE        JR $+5 ;пропуск BOUNCE_HEROnfall        CALL BOUNCE ;ставит флаг касания        CALL CPlrf   ;взяли бонус/напоролись на врага?       CALL DETBON_ENEMY      ;01-враг (?)      ;10-бонус       PUSH DE        CP %10        CALL Z,_HEROBONPP       POP DE        LD C,(IX+4) ;X  ;фаза=X*0.2122~=(X-X/8)/4        LD A,(IX+5) ;'X        RRA         LD A,C        RRA         RRA         RRA         SUB C        RRA         RRA         AND 15        LD (IX+1),A_EMPTY  JP programQ_HEROBONPP     ;ищем этот бонус в списке       LD HL,#3018 ;размеры персонажа в полупикселях (hgt, бок)       CALL COLLBALL ;коллизии ;CY=коллизия        RET NC      ;HL=адрес приза        LD A,(HL)        CP IDweight       JP Z,_HEROWGT        CP IDbottle       JP Z,_HEROBOT        CP IDexit       JP Z,_HEROEXIT        CP IDapple       jr Z,_HEROapp        CP IDhourglass       JP Z,_HEROHG        CP IDdiam       JP Z,_HERODIAM        CP IDkey       JP Z,_HEROKEY        RET _HEROapp        LD (HL),ID15        LD DE,15       PUSH DE        LD DE,10        ADD HL,DE ;time8        LD (HL),50       IF fx        LD A,fxfood        CALL AFXPRAY       ELSE         LD DE,BBONUS        CALL NEW