        LD LY,-3        CALL BOUNCE        LD HL,#000 ;1 фаза        CALL PHASER        JP P,programQ        LD A,2        LD (gameover),A       ENDIF programQ        LD BC,Lunit        ADD IX,BC        JP IQ_NUMBER        DEC BC        DEC BC        LD (IX+2),C        LD (IX+3),B        DEC (IX+10)        CALL Z,DELPERS        JP programQ_EXIT        LD A,(keys)        OR A        jr NZ,_EXITnK0        LD (IX+1),1 ;было 0=sprempty_EXITnK0        JP programQDELprogQ_        CALL DELPERS        JP IQMOVEANIM;двигаем синхронные анимацииDIAMtime=$+1        LD A,1DIAMHL=$+1        LD HL,DIAMANI        LD DE,DIAMFIG        CALL DIAMTIME        LD (DIAMtime),A        LD (DIAMHL),HLEXITtime=$+1        LD A,1EXITHL=$+1        LD HL,EXITANI        LD DE,EXITFIG        CALL DIAMTIME        LD (EXITtime),A        LD (EXITHL),HLKEYtime=$+1        LD A,1KEYHL=$+1        LD HL,KEYANI        LD DE,KEYFIG        CALL DIAMTIME        LD (KEYtime),A        LD (KEYHL),HLWGTtime=$+1        LD A,1WGTHL=$+1        LD HL,WGTANI        LD DE,WGTFIG        CALL DIAMTIME        LD (WGTtime),A        LD (WGTHL),HLBOTtime=$+1        LD A,1BOTHL=$+1        LD HL,BOTANI        LD DE,BOTFIG        CALL DIAMTIME        LD (BOTtime),A        LD (BOTHL),HLSPItime=$+1        LD A,1SPIHL=$+1        LD HL,SPIANI        LD DE,SPIFIG        CALL DIAMTIME        LD (SPItime),A        LD (SPIHL),HLCHEtime=$+1        LD A,1CHEHL=$+1        LD HL,CHEANI        LD DE,CHEFIG        CALL DIAMTIME        LD (CHEtime),A        LD (CHEHL),HLHOURtime=$+1        LD A,1HOURHL=$+1        LD HL,HOURANI        LD DE,HOURFIG        CALL DIAMTIME        LD (HOURtime),A        LD (HOURHL),HL        RET DIAMTIME        DEC A        RET NZ        OR (HL)        INC HL        jr NZ,DIAMnBE        LD A,(HL)        INC HL        LD H,(HL),L,A        LD A,(HL)        INC HLDIAMnBE LDI         LDI         RET DIAMANI